"""Interval estimation and the test/CI duality."""
from nodespec import N

N("confidence_set", "definition", "intervals",
  "A 1 - alpha confidence set for theta is a data-dependent set C(X) subset Theta with P_theta( theta in C(X) ) >= 1 - alpha for every theta (an interval, in one dimension).",
  parseable="P_theta( theta in C(X) ) >= 1 - alpha   for every theta in Theta",
  symbols={"C(X)": "the confidence set, type: random subset of Theta",
           "1 - alpha": "the confidence LEVEL (a property of the procedure, not of one realized interval)",
           "coverage": "theta -> P_theta(theta in C(X)), which should be >= 1 - alpha throughout"},
  tcn="A frequentist coverage guarantee about the RANDOM set C(X), holding for all theta. A realized interval [l, u] either contains the fixed unknown theta or not -- the '95%' describes the long-run behaviour of the rule, not a probability about theta.",
  regime="exact",
  spec=["exact: Xbar +- t_{n-1, 1-alpha/2} S/sqrt(n) for a normal mean -- coverage exactly 1 - alpha",
        "asymptotic: theta_hat +- z_{1-alpha/2} SE -- coverage -> 1 - alpha",
        "conservative: a Bonferroni-adjusted simultaneous set has coverage >= 1 - alpha, often strictly"],
  cxd={"coverage_for_every_theta": "the Wald interval for a binomial p has coverage that DIPS well below 1 - alpha for p near 0 or 1 and small n (down to ~0.8 for a nominal 0.95) -- the Clopper-Pearson or Wilson interval fixes it",
       "the_set_is_pre-specified": "choosing which parameter to bracket after seeing the data (selective inference) destroys the coverage guarantee"},
  misuse=["saying 'there is a 95% probability that theta is in [l, u]' for a realized interval -- theta is not random",
          "comparing two 95% intervals by whether they overlap as a test (the overlap test is conservative and low-powered)"],
  apps=["every reported '95% CI' in a clinical trial, poll, or physics measurement",
        "the CI is the dual of the hypothesis test (confidence_set_test_duality) -- reporting the interval subsumes the test"],
  related={"required_by": ["coverage_probability", "pivot_method", "confidence_set_test_duality", "wald_interval"],
           "dual_of": ["test_function"], "commonly_confused_with": ["credible_interval"]},
  sources=["casella_berger_2e", "neyman_1937"])

N("coverage_probability", "definition", "intervals",
  "The coverage probability of a confidence procedure C(.) at theta is beta_C(theta) = P_theta( theta in C(X) ); the procedure has confidence level 1 - alpha if inf_theta beta_C(theta) >= 1 - alpha.",
  parseable="beta_C(theta) = P_theta( theta in C(X) );   level = inf_theta beta_C(theta)",
  symbols={"beta_C(theta)": "coverage as a function of theta -- ideally flat at 1 - alpha"},
  tcn="A function of theta, the CI analogue of a test's power function. 'Exact' procedures have beta_C(theta) = 1 - alpha for all theta; discrete data usually force beta_C(theta) > 1 - alpha somewhere (conservative) and it oscillates in theta.",
  regime="exact",
  spec=["normal mean t-interval: beta_C(theta) = 1 - alpha exactly, for all (mu, sigma^2)",
        "binomial Clopper-Pearson: beta_C(p) >= 1 - alpha always, with sawtooth over-coverage",
        "binomial Wald: beta_C(p) oscillates and undershoots badly near the boundary"],
  cxd={"none_all_hypotheses_essential": "coverage is defined for any procedure; the content is whether inf_theta beta_C >= 1 - alpha"},
  misuse=["reporting the nominal level without checking actual coverage for discrete / small-sample / boundary problems",
          "averaging coverage over a prior and reporting that as 'the coverage' (that is a Bayesian, not frequentist, quantity)"],
  related={"uses": ["confidence_set"]},
  sources=["casella_berger_2e", "brown_cai_dasgupta_2001"])

N("pivotal_quantity", "definition", "intervals",
  "A pivotal quantity is a function Q(X, theta) of the data and the parameter whose distribution is the same for every theta in Theta.",
  parseable="Q(X, theta):  the law of Q(X, theta) under P_theta does not depend on theta",
  symbols={"Q(X, theta)": "the pivot -- involves theta, so it is NOT a statistic",
           "its (theta-free) distribution": "known, so its quantiles can be looked up"},
  tcn="A pivot mixes data and parameter in a way that cancels theta's effect on the distribution. It is the engine for exact confidence sets: bracket Q by its known quantiles, then solve for theta.",
  regime="exact",
  spec=["N(mu, sigma^2 known): Q = sqrt(n)(Xbar - mu)/sigma ~ N(0,1), pivotal",
        "N(mu, sigma^2): Q = sqrt(n)(Xbar - mu)/S ~ t_{n-1}, pivotal",
        "N(mu, sigma^2): Q = (n-1) S^2 / sigma^2 ~ chi^2_{n-1}, pivotal for sigma^2",
        "any continuous F_theta: Q = F_theta(X) ~ Uniform(0,1) -- the probability integral transform is a universal (if often intractable) pivot"],
  cxd={"exactly_theta_free_law": "an ASYMPTOTIC pivot (theta_hat - theta)/SE -> N(0,1) is only approximately pivotal at finite n -- the resulting Wald interval has approximate coverage",
       "Behrens-Fisher": "(Xbar - Ybar - delta) / sqrt(S_X^2/n + S_Y^2/m) is NOT exactly pivotal when sigma_X != sigma_Y -- its df depends on the unknown ratio (hence Welch's approximation)"},
  misuse=["treating a quantity as pivotal because it 'looks standardized' without checking its law is genuinely theta-free",
          "using a location-scale pivot when a nuisance parameter (an unknown correlation, an unknown shape) remains in its distribution"],
  related={"required_by": ["pivot_method"], "uses": []},
  sources=["casella_berger_2e"])

N("pivot_method", "algorithm", "intervals",
  "Given a pivot Q(X, theta) with known distribution, pick constants a, b with P(a <= Q(X, theta) <= b) = 1 - alpha, then C(X) = { theta : a <= Q(X, theta) <= b } is an exact 1 - alpha confidence set.",
  parseable="C(X) = { theta : a <= Q(X, theta) <= b },  where P( a <= Q <= b ) = 1 - alpha",
  symbols={"a, b": "quantiles of the pivot's known distribution (e.g. +- t_{n-1, 1-alpha/2})",
           "'invert the pivot'": "solve the double inequality in theta"},
  tcn="An exact construction: coverage is 1 - alpha BY CONSTRUCTION because {theta in C(X)} = {a <= Q(X, theta) <= b} as events, and the latter has probability 1 - alpha for every theta (pivotality). The set is an interval iff Q is monotone in theta.",
  regime="exact",
  hyps=["pivotal_quantity"],
  proof=("event identity { theta in C(X) } = { a <= Q(X, theta) <= b }; take P_theta of both sides; the right side has probability 1 - alpha independent of theta",
         "pivotal_quantity", "core",
         "the event-identity / probability-transfer step is proof-checks.lean Stat.pivot_coverage -- P{theta in C} = P{a <= Q <= b} = 1 - alpha"),
  spec=["normal mean, sigma known: invert -z <= sqrt(n)(Xbar - mu)/sigma <= z  =>  Xbar +- z sigma/sqrt(n)",
        "normal variance: invert chi^2_{lo} <= (n-1)S^2/sigma^2 <= chi^2_{hi}  =>  ( (n-1)S^2/chi^2_{hi}, (n-1)S^2/chi^2_{lo} ) -- asymmetric",
        "the choice of (a, b) is free; equal-tailed is conventional, shortest-interval is an alternative"],
  cxd={"pivotal_quantity": "with only an asymptotic pivot the coverage is 1 - alpha + O(n^{-1/2}) -- the method still 'works' but is no longer exact",
       "monotone_in_theta": "if Q is not monotone in theta the inverted set can be a union of intervals or empty"},
  misuse=["inverting an asymptotic pivot and calling the interval 'exact'",
          "always using equal-tailed quantiles when the pivot's distribution is very skewed (chi^2 with small df) -- the equal-tailed interval is far from shortest"],
  related={"required_by": ["normal_mean_ci_known_variance", "normal_mean_ci_unknown_variance", "normal_variance_ci"],
           "uses": ["pivotal_quantity"]},
  sources=["casella_berger_2e"])

N("confidence_set_test_duality", "theorem", "intervals",
  "Confidence sets and hypothesis tests are equivalent: if { phi_{theta_0} } is a family of level-alpha tests of H0: theta = theta_0, then C(x) = { theta_0 : phi_{theta_0}(x) does not reject } is a 1 - alpha confidence set; conversely, from a 1 - alpha confidence set C, the test 'reject H0: theta = theta_0 iff theta_0 not in C(x)' has level alpha.",
  parseable="C(x) = { theta_0 : test of H0: theta = theta_0 accepts at x }   <==>   reject theta_0  iff  theta_0 not in C(x)",
  symbols={"the acceptance region A(theta_0) = { x : phi_{theta_0}(x) = 0 }": "and C(x) = { theta_0 : x in A(theta_0) } -- a 'horizontal slice' vs 'vertical slice' of the same set in (x, theta) space"},
  tcn="An exact equivalence, holding at finite n. Proof: P_{theta_0}(theta_0 in C(X)) = P_{theta_0}(X in A(theta_0)) = 1 - (size of the test) >= 1 - alpha.",
  regime="exact",
  hyps=[],
  proof=("the event { theta_0 in C(X) } equals { X in A(theta_0) } by definition; its probability under theta_0 is 1 - size(phi_{theta_0}) >= 1 - alpha",
         "size_of_test", "core",
         "the slice/transpose identity {theta_0 in C(x)} = {x in A(theta_0)} and the probability transfer is proof-checks.lean Stat.ci_test_duality"),
  spec=["the t-interval Xbar +- t S/sqrt(n) is exactly the set of mu_0 NOT rejected by the two-sided one-sample t-test",
        "inverting the LRT gives the likelihood-ratio confidence interval; inverting the score test gives the score interval (Wilson, for a proportion)",
        "a UMP test inverts to a uniformly most accurate (shortest expected length among unbiased) confidence set"],
  cxd={"none_all_hypotheses_essential": "the duality is a definitional equivalence; the only requirement is that the test have level alpha (or the CI have coverage 1 - alpha)"},
  misuse=["reporting BOTH a p-value and a CI as if independent evidence -- for the same procedure they carry the same information",
          "inverting a test with poor properties (the Wald test for a proportion) and being surprised the interval also has poor coverage"],
  apps=["'is 0 in the 95% CI?' as a visual significance test in every forest plot and regression table",
        "profile-likelihood confidence intervals in nonlinear models are the LRT inverted"],
  related={"dual_of": ["test_function"], "uses": ["size_of_test"], "required_by": []},
  sources=["casella_berger_2e", "lehmann_romano_tsh"])

N("normal_mean_ci_known_variance", "proposition", "intervals",
  "For X_1..X_n iid N(mu, sigma^2) with sigma^2 KNOWN, the interval Xbar +- z_{1-alpha/2} sigma / sqrt(n) has coverage exactly 1 - alpha for every mu.",
  parseable="C(X) = Xbar +- z_{1-alpha/2} sigma/sqrt(n);   P_mu(mu in C(X)) = 1 - alpha",
  symbols={"z_{1-alpha/2}": "the upper alpha/2 quantile of N(0,1) (1.96 for alpha = 0.05)"},
  tcn="Exact. Invert the pivot sqrt(n)(Xbar - mu)/sigma ~ N(0,1). Width 2 z sigma/sqrt(n) is NON-random (sigma known) -- the only randomness is the center.",
  regime="exact",
  hyps=[],
  proof=("pivot method with Q = sqrt(n)(Xbar - mu)/sigma ~ N(0,1)",
         "pivot_method", "core", None),
  spec=["alpha = 0.05: Xbar +- 1.96 sigma/sqrt(n)",
        "the 'margin of error' of a poll (with sigma^2 = p(1-p) plugged in) -- a slight abuse since sigma^2 is then estimated",
        "sample size for a target width w: n = (2 z sigma / w)^2"],
  cxd={"sigma_known": "sigma is essentially never known; using an estimate S in the z-interval undercovers at small n -- that is exactly why the t-interval exists (normal_mean_ci_unknown_variance)",
       "normality": "for non-normal data the coverage is approximate (1 - alpha + O(n^{-1/2}) by the CLT), reasonable for large n"},
  misuse=["plugging S for sigma and keeping z (rather than t) at small n",
          "treating the realized interval's endpoints as a 95%-probable range for mu"],
  related={"uses": ["pivot_method", "sample_mean"], "approximated_by": []},
  sources=["casella_berger_2e"])

N("normal_mean_ci_unknown_variance", "proposition", "intervals",
  "For X_1..X_n iid N(mu, sigma^2) with sigma^2 UNKNOWN, the interval Xbar +- t_{n-1, 1-alpha/2} S / sqrt(n) has coverage exactly 1 - alpha for every (mu, sigma^2). This is 'the' confidence interval for a mean.",
  parseable="C(X) = Xbar +- t_{n-1, 1-alpha/2} S/sqrt(n);   P_{mu,sigma^2}(mu in C(X)) = 1 - alpha",
  symbols={"t_{n-1, 1-alpha/2}": "the upper alpha/2 quantile of t_{n-1} (> z, converging to it as n grows)",
           "the width 2 t S/sqrt(n)": "now RANDOM through S"},
  tcn="Exact. Invert the pivot sqrt(n)(Xbar - mu)/S ~ t_{n-1} (t_statistic_distribution). The t quantile (wider than z) is the exact price of estimating sigma.",
  regime="exact",
  hyps=[],
  proof=("pivot method with Q = sqrt(n)(Xbar - mu)/S ~ t_{n-1}",
         "t_statistic_distribution", "core", None),
  spec=["n = 2, alpha = 0.05: t_{1, 0.975} = 12.7 -- the interval is enormous, honestly reflecting near-zero information about sigma",
        "n >= 30: t_{n-1} approx z, the t- and z-intervals nearly coincide",
        "paired data: apply to the within-pair differences"],
  cxd={"normality": "for skewed data at small n coverage departs from 1 - alpha (the t-interval is more robust than the chi^2 variance interval but not immune); a bootstrap-t or BCa interval can do better",
       "iid": "positively correlated observations => S underestimates Var(Xbar) => the interval is too narrow => undercoverage"},
  misuse=["using z instead of t at small n (undercoverage)",
          "applying it to a proportion with small np (use Wilson / Clopper-Pearson)",
          "reporting it after choosing the outcome variable based on which gave the smallest p-value"],
  apps=["the default 'mean +- CI' in every statistics package, spreadsheet, and scientific paper",
        "dual to the one-sample t-test (confidence_set_test_duality)"],
  related={"uses": ["pivot_method", "t_statistic_distribution"], "approximates": ["wald_interval"],
           "commonly_confused_with": ["normal_mean_ci_known_variance"]},
  sources=["student_1908", "casella_berger_2e"])

N("normal_variance_ci", "proposition", "intervals",
  "For X_1..X_n iid N(mu, sigma^2), the interval ( (n-1)S^2 / chi^2_{n-1, 1-alpha/2},  (n-1)S^2 / chi^2_{n-1, alpha/2} ) has coverage exactly 1 - alpha for sigma^2. It is asymmetric about S^2.",
  parseable="C(X) = ( (n-1)S^2 / chi^2_{n-1,1-alpha/2},  (n-1)S^2 / chi^2_{n-1,alpha/2} )",
  symbols={"chi^2_{n-1, q}": "the q-quantile of chi^2_{n-1}",
           "asymmetry": "the chi^2 distribution is right-skewed, so the interval is not S^2 +- something"},
  tcn="Exact under normality. Invert the pivot (n-1)S^2/sigma^2 ~ chi^2_{n-1}. Equal-tailed is conventional but far from shortest for small n.",
  regime="exact",
  hyps=[],
  proof=("pivot method with Q = (n-1)S^2/sigma^2 ~ chi^2_{n-1}",
         "scaled_sample_variance_chi_squared", "core", None),
  spec=["take sqrt of the endpoints for a CI on sigma (the SD)",
        "n = 10, alpha = 0.05: the interval spans roughly (0.47 S^2, 3.3 S^2) -- variance is hard to pin down",
        "the shortest 1 - alpha interval uses unequal tail probabilities chosen to minimize length"],
  cxd={"normality": "THIS PROCEDURE HAS NO ROBUSTNESS. For data with kurtosis != 3 (any non-normal shape) the coverage can be far from 1 - alpha even for large n, because (n-1)S^2/sigma^2 is not chi^2_{n-1} and its shape depends on the 4th moment. Use a bootstrap or a kurtosis-corrected interval."},
  misuse=["using it for a variance CI with visibly non-normal data -- unlike the t-interval for the mean, this one does not self-correct via the CLT at usual n",
          "reporting a symmetric S^2 +- interval"],
  related={"uses": ["pivot_method", "scaled_sample_variance_chi_squared"]},
  sources=["casella_berger_2e"])

N("wald_interval", "definition", "intervals",
  "A Wald confidence interval for a scalar theta is theta_hat +- z_{1-alpha/2} se(theta_hat), where theta_hat is asymptotically normal and se(theta_hat) is a consistent estimate of its standard deviation (typically from the inverse observed information). Coverage -> 1 - alpha as n -> inf.",
  parseable="C(X) = theta_hat +- z_{1-alpha/2} se(theta_hat);   P_theta(theta in C(X)) -> 1 - alpha",
  symbols={"se(theta_hat)": "estimated standard error, e.g. 1/sqrt(n I(theta_hat)) or a diagonal of the inverse observed information",
           "z_{1-alpha/2}": "normal quantile (t_{n-p} in the regression case for a finite-sample refinement)"},
  tcn="An ASYMPTOTIC interval. Its coverage is 1 - alpha only in the limit; it is symmetric by construction, which is its main weakness near a parameter boundary or for a skew-sampling-distribution estimator.",
  regime="asymptotic",
  hyps=["fisher_information_positive_definite"],
  proof=("theta_hat asymptotically N(theta, se^2) + se consistent => (theta_hat - theta)/se -> N(0,1) (Slutsky); invert",
         "asymptotic_normality_estimator", "cited", None),
  spec=["MLE: theta_hat +- z / sqrt(n I(theta_hat)) (large_sample_wald_interval)",
        "binomial proportion: p_hat +- z sqrt(p_hat(1-p_hat)/n) -- the notorious Wald interval for p, which undercovers near 0 and 1",
        "a transformed parameter g(theta): use the delta-method se |g'(theta_hat)| se(theta_hat) (delta_method_standard_error), or better, build the interval on the scale where normality is best and back-transform"],
  cxd={"fisher_information_positive_definite": "near a boundary (p near 0/1, a variance component near 0) the sampling distribution is skewed and one-sided; the symmetric Wald interval can extend outside the parameter space and badly undercover -- the score (Wilson) or LR interval is the fix",
       "sqrt_n_normality": "for a non-sqrt(n) estimator (uniform endpoint) the Wald recipe is simply invalid"},
  misuse=["using the Wald interval for a proportion with small np or p near 0/1 (use Wilson or Clopper-Pearson)",
          "reporting a Wald CI that includes impossible values (negative variance, probability > 1) without reconsidering the scale",
          "trusting its coverage at the n you have rather than in the limit"],
  apps=["the default CI reported next to every coefficient in a fitted GLM / Cox model / SEM",
        "its poor small-sample behaviour for proportions is why epidemiology moved to Wilson score intervals"],
  related={"uses": ["asymptotic_normality_estimator", "fisher_information"],
           "approximated_by": [], "approximates_from": ["normal_mean_ci_unknown_variance"],
           "required_by": ["delta_method_standard_error", "large_sample_wald_interval"]},
  sources=["casella_berger_2e", "brown_cai_dasgupta_2001"])

N("delta_method_standard_error", "proposition", "intervals",
  "If sqrt(n)(theta_hat - theta) -> N(0, v(theta)) and g is differentiable at theta with g'(theta) != 0, then sqrt(n)(g(theta_hat) - g(theta)) -> N(0, g'(theta)^2 v(theta)); so se(g(theta_hat)) = |g'(theta_hat)| se(theta_hat), giving an asymptotic interval for g(theta).",
  parseable="se( g(theta_hat) ) = | g'(theta_hat) | . se( theta_hat )",
  symbols={"g'(theta)": "the derivative (gradient, then g'(theta)^T V g'(theta) in the vector case)",
           "the linearization": "g(theta_hat) approx g(theta) + g'(theta)(theta_hat - theta)"},
  tcn="A first-order (Taylor) propagation of uncertainty. Asymptotic. Fails when g'(theta) = 0 (then the limit is a scaled chi^2_1, the 'second-order delta method') or g is not differentiable.",
  regime="asymptotic",
  hyps=[],
  proof=("first-order Taylor of g at theta_hat, then Slutsky (the remainder is o_p(1/sqrt n))",
         "prob_delta_method", "cited", None),
  spec=["odds ratio from log-odds: se(OR) = OR . se(log OR) -- but the CI is better built on the log scale and exponentiated",
        "se of p_hat(1 - p_hat) is |1 - 2 p_hat| se(p_hat) -- ZERO at p_hat = 1/2, where the first-order method fails and Var(p_hat(1-p_hat)) = O(1/n^2)",
        "se of a ratio Xbar/Ybar (Ybar bounded away from 0): the classic ratio-estimator variance formula"],
  cxd={"g_prime_nonzero": "g(theta) = theta^2 at theta = 0: g'(0) = 0, so the first-order delta method gives se = 0. The truth is n theta_hat^2 -> sigma^2 chi^2_1 -- a completely different (one-sided, non-normal) limit.",
       "g_differentiable": "g(theta) = |theta| at 0, or a max/min functional -- not differentiable, delta method inapplicable"},
  misuse=["applying it where g'(theta_hat) is near 0 and reporting an absurdly small SE",
          "building a symmetric CI for a bounded quantity (a probability, a correlation) on the natural scale rather than a variance-stabilizing scale (logit, Fisher z)"],
  apps=["the universal 'error propagation' formula in physics and chemistry lab courses",
        "standard errors for predicted probabilities, marginal effects, EC50s, and elasticities in applied econometrics/biostatistics"],
  related={"uses": ["wald_interval", "ra_differentiability"], "special_case_of": ["prob_delta_method"]},
  sources=["van_der_vaart_asymptotic", "casella_berger_2e"])

N("large_sample_wald_interval", "proposition", "intervals",
  "From the MLE, theta_hat_MLE +- z_{1-alpha/2} / sqrt(n I(theta_hat_MLE)) (or using the observed information -d^2 ell(theta_hat)) is a confidence interval with coverage -> 1 - alpha.",
  parseable="C(X) = theta_hat_MLE +- z_{1-alpha/2} / sqrt( n I(theta_hat) )",
  symbols={"n I(theta_hat)": "the estimated sample Fisher information -- or the observed information J(theta_hat) = -d^2 ell(theta_hat)",
           "observed vs expected information": "the observed version has slightly better finite-sample properties (Efron-Hinkley 1978)"},
  tcn="The Wald interval specialized to the MLE, using mle_asymptotic_normality's variance I(theta_0)^{-1}. Asymptotic; shares the Wald interval's boundary weaknesses.",
  regime="asymptotic",
  hyps=["true_parameter_interior", "fisher_information_positive_definite", "log_likelihood_smooth"],
  proof=("mle_asymptotic_normality gives sqrt(n)(theta_hat - theta) -> N(0, I^{-1}); I(theta_hat) -> I(theta) consistently; Slutsky; invert",
         "mle_asymptotic_normality", "cited", None),
  spec=["Poisson rate: lambda_hat +- z sqrt(lambda_hat / n) since I(lambda) = 1/lambda",
        "logistic regression coefficients: the standard reported CI, beta_hat_j +- z se_j with se_j from the inverse observed information",
        "prefer the profile-likelihood (LR) interval when the log-likelihood is visibly asymmetric"],
  cxd={"true_parameter_interior": "near a boundary the interval extends past the parameter space and undercovers -- use the LR interval, which respects the likelihood's shape",
       "log_likelihood_smooth": "non-regular model: the interval is invalid (wrong rate / wrong shape)"},
  misuse=["reporting it for a small sample where the log-likelihood is far from quadratic (use LR / profile intervals)",
          "using expected information I(theta_hat) when the model may be misspecified -- then the sandwich SE is right"],
  related={"uses": ["mle_asymptotic_normality", "wald_interval"], "approximates": []},
  sources=["casella_berger_2e", "efron_hinkley_1978"])

N("credible_interval", "definition", "intervals",
  "A 1 - alpha credible interval (region) for theta is a set C(x) with posterior probability P(theta in C(x) | X = x) = 1 - alpha; common choices are the equal-tailed interval (alpha/2 in each posterior tail) and the highest-posterior-density (HPD) region { theta : pi(theta | x) >= k }.",
  parseable="P( theta in C(x) | X = x ) = 1 - alpha",
  symbols={"pi(theta | x)": "the posterior density", "HPD region": "the shortest such set for a unimodal posterior",
           "1 - alpha": "a posterior probability -- a statement about theta given THIS data and the prior"},
  tcn="A posterior-probability statement, conditional on the observed x and the prior. Fundamentally different from a confidence interval: here theta is random (posterior) and the interval is fixed given x; there theta is fixed and the interval is random. They coincide asymptotically for regular models (bernstein_von_mises).",
  status_label="definition",
  regime="bayesian",
  hyps=[],
  spec=["Beta(a+s, b+n-s) posterior: the equal-tailed 95% credible interval is (Beta quantile 0.025, Beta quantile 0.975)",
        "Normal-Normal: the credible interval is posterior mean +- 1.96 posterior SD (posterior is Gaussian)",
        "HPD vs equal-tailed: identical for a symmetric posterior; HPD is shorter and can be disjoint for a bimodal posterior"],
  cxd={"proper_posterior": "an improper posterior (from an improper prior with no finite normalizer) has no credible interval -- reported intervals are then meaningless",
       "prior_is_defensible": "a 95% credible interval inherits the prior; with a strong prior and little data it mostly reflects the prior, which must be disclosed"},
  misuse=["reporting a credible interval as if it had frequentist coverage without invoking Bernstein-von Mises (valid only for regular parametric models, large n)",
          "using a vague / improper prior and calling the credible interval 'objective'",
          "HPD regions are not parametrization-invariant -- reparametrize and the HPD set changes (the equal-tailed interval transforms cleanly under monotone maps)"],
  apps=["the standard interval summary in Bayesian data analysis, from clinical trials (Bayesian adaptive designs) to cosmology (parameter constraints from the CMB)"],
  related={"uses": ["bayes_estimator", "prob_conditional_distribution"], "commonly_confused_with": ["confidence_set"],
           "approximated_by": ["bernstein_von_mises"]},
  sources=["gelman_bda3", "robert_bayesian_choice"])
